from typing import TypedDict
from langgraph.graph import StateGraph, START, END
from langgraph.types import Command

class State(TypedDict):
    messages: list[str]

def root_target(state: State):
    return {"messages": state["messages"] + ["root target"]}

def deep_node(state: State):
    return Command(
        graph=Command.PARENT,
        goto="root_target",
        update={"messages": state["messages"] + ["deep"]},
    )

# child_graph_2 contains deep_node.
# child_graph_1 contains child_graph_2.
# root_graph contains child_graph_1 and root_target.
# The command is returned from deep_node during execution of child_graph_2.
# The application expects Command.PARENT to route to the immediate parent
# graph and resolve root_target there.
